import{_ as a,o as i,c as n,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Server gameplay policy","description":"","frontmatter":{"pageId":"admins/gameplay-policy","contentRevision":5},"headers":[],"relativePath":"en/admins/gameplay-policy.md","filePath":"en/admins/gameplay-policy.md"}'),t={name:"en/admins/gameplay-policy.md"};function o(s,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="server-gameplay-policy" tabindex="-1">Server gameplay policy <a class="header-anchor" href="#server-gameplay-policy" aria-label="Permalink to &quot;Server gameplay policy&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Before opening a server, publish rules for economy, newcomer protection, raids, incidents and storage. Economy controls parcel/lot limits, fees, storage charges and threat restrictions. Raids controls raider counts, cooldowns, loot, peaceful mode and lifetimes. Incidents controls its catalog, queue and prices. Live controls deadlines, pauses and stream limits.</p><p>Integrity controls dev mode, wealth changes and scenario modifications. Hygiene archives sufficiently old inactive colonies under wealth/age conditions and defines public wealth bands. Disabling a check requires understanding its semantics, not assigning an arbitrary zero.</p><p>For an incident, first freeze the relevant subsystem, preserve IDs and audit, inspect escrow, then cancel or unfreeze. Verify mail returns.</p><h2 id="policy-example" tabindex="-1">Example of a coherent server policy <a class="header-anchor" href="#policy-example" aria-label="Permalink to &quot;Example of a coherent server policy {#policy-example}&quot;">​</a></h2><p>Decide raids, newcomer/low-wealth protection, peaceful exit delay and available hostile incidents before launch. Explain real/copies and warned/instant; chat blocking is not raid protection.</p><p>Economic rules should disclose fees, pawn/perishable storage charges, debt, threat restrictions and treasury distribution on disbanding. Offline colonies are not continuously simulated by the server. Influence is an opt-in overlay, not land ownership. These boundaries matter more than promises of automatic behavior.</p><h2 id="freeze-runbook" tabindex="-1">Freeze procedure during an incident <a class="header-anchor" href="#freeze-runbook" aria-label="Permalink to &quot;Freeze procedure during an incident {#freeze-runbook}&quot;">​</a></h2><p>Record time, player, ID and state; freeze the relevant subsystem and preserve audit. Inspect wallets/escrow/parcels and pending client replay. Freeze does not undo settled operations; auctions may defer settlement.</p><p>Choose a supported cancellation/return or remove the cause. Verify recipients/mail before unfreezing and watch the queue. Do not grant guessed silver compensation: a later automatic return could pay twice.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Auction, procurement, social and influence constants are not necessarily configurable. Storage charges may create debt. A freeze defers auction settlement; it is not an automatic refund. Influence does not grant territorial rights.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./configuration">Configuration reference</a></li><li><a href="./administration">Panel and moderation</a></li><li><a href="./../players/raids-incidents">Raids and paid incidents</a></li></ul>',16)])])}const h=a(t,[["render",o]]);export{m as __pageData,h as default};
